// Generated by tools/audio/pack.py from tools/gen/sound_recipe.py and the takes it measured: never edited by hand.
//
// Every sound effect there is, each with its takes (the model's attempts, numbered from 1), which of them the
// game plays (`use`: chosen by measuring, or by ear when `byEar`), how long each is, the gain that evens its
// loudness with the others, and anything the measuring found wrong with it. The files are
// static/audio/sfx/<name>_<n>.ogg (Opus). The music's table is pieces.ts (tools/audio/music.mjs).

export interface Take {
  n: number
  seconds: number
  /** what evens its loudness with the other effects' (music: 1) */
  gain: number
  flags: string[]
}

export interface Clip {
  /** its group, and what it is in plain words */
  group: string
  label: string
  /** a steady sound that repeats without a seam */
  loop: boolean
  /** the takes the game plays (more than one: it takes turns) */
  use: number[]
  byEar: boolean
  /** made since James last listened */
  new?: boolean
  takes: Take[]
}

